#include "tangra_fc/waypoint_executor.hpp"
#include <cmath>
namespace tangra::fc {
bool WaypointExecutor::load(std::vector<Waypoint> goals){for(const auto&g:goals){if(!g.valid||g.acceptance_radius_m<=0||g.timeout_ms==0){reason_=MissionLifecycleReasonV1::INVALID_GOAL;return false;}}goals_=std::move(goals);index_=0;reason_=MissionLifecycleReasonV1::NONE;return!goals_.empty();}
void WaypointExecutor::start(std::uint64_t now){if(goals_.empty()){reason_=MissionLifecycleReasonV1::INVALID_GOAL;lifecycle_.request(MissionLifecycleStateV1::ABORT,reason_);return;}if(lifecycle_.request(MissionLifecycleStateV1::ACTIVE,MissionLifecycleReasonV1::NONE))goal_start_ms_=now;}
ExecutorStatus WaypointExecutor::update(const ExecutorObservation&o){if(lifecycle_.state()!=MissionLifecycleStateV1::ACTIVE)return status();if(index_>=goals_.size()){reason_=MissionLifecycleReasonV1::SEQUENCE_COMPLETE;lifecycle_.request(MissionLifecycleStateV1::COMPLETE,reason_);return status();}if(!o.valid||!o.fresh)return status();const auto&g=goals_[index_];if(o.now_ms<goal_start_ms_||o.now_ms-goal_start_ms_>g.timeout_ms){reason_=MissionLifecycleReasonV1::TIMEOUT;lifecycle_.request(MissionLifecycleStateV1::ABORT,reason_);return status();}double dx=g.x-o.x,dy=g.y-o.y,dz=g.z-o.z;if(std::sqrt(dx*dx+dy*dy+dz*dz)<=g.acceptance_radius_m){reason_=MissionLifecycleReasonV1::ARRIVED;++index_;if(index_>=goals_.size()){reason_=MissionLifecycleReasonV1::SEQUENCE_COMPLETE;lifecycle_.request(MissionLifecycleStateV1::COMPLETE,reason_);}else goal_start_ms_=o.now_ms;}return status();}
void WaypointExecutor::hold(){reason_=MissionLifecycleReasonV1::HOLD_REQUESTED;lifecycle_.request(MissionLifecycleStateV1::HOLD,reason_);}
void WaypointExecutor::abort(){reason_=MissionLifecycleReasonV1::ABORT_REQUESTED;lifecycle_.request(MissionLifecycleStateV1::ABORT,reason_);}
ExecutorStatus WaypointExecutor::status()const{ExecutorStatus s;s.active_index=index_;s.count=goals_.size();s.progress=goals_.empty()?0.0:static_cast<double>(index_)/goals_.size();s.reason=reason_;s.has_active_goal=index_<goals_.size();return s;}
}
